import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> {'side', 'price', 'qty', 'cancelled'}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = [0]

    def next_seq():
        s = seq_counter[0]
        seq_counter[0] += 1
        return s

    def process_incoming(incoming_side, incoming_price, incoming_qty, is_market, incoming_id):
        local_trades = []
        heap = sell_heap if incoming_side == 'buy' else buy_heap
        while incoming_qty > 0 and heap:
            key, seq, oid = heap[0]
            info = orders_info.get(oid)
            if info is None or info['cancelled'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            resting_price = info['price']
            if not is_market:
                if incoming_side == 'buy' and resting_price > incoming_price:
                    break
                if incoming_side == 'sell' and resting_price < incoming_price:
                    break
            # perform match
            heapq.heappop(heap)
            trade_qty = min(incoming_qty, info['qty'])
            if incoming_side == 'buy':
                local_trades.append([incoming_id, oid, resting_price, trade_qty])
            else:
                local_trades.append([oid, incoming_id, resting_price, trade_qty])
            incoming_qty -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] > 0:
                heapq.heappush(heap, (key, seq, oid))
            else:
                info['cancelled'] = True  # mark as done (fully filled)
        return local_trades, incoming_qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and not info['cancelled'] and info['qty'] > 0:
                info['cancelled'] = True
            continue

        oid = order[1]
        side = order[2]

        if typ == 'limit':
            price = order[3]
            qty = order[4]
            is_market = False
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
            is_market = False
        elif typ == 'market':
            price = None
            qty = order[3]
            is_market = True
        else:
            continue

        local_trades, remaining = process_incoming(side, price, qty, is_market, oid)
        trades.extend(local_trades)

        if typ == 'limit' and remaining > 0:
            orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'cancelled': False}
            seq = next_seq()
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        # for ioc/market, remainder is discarded (do nothing)
        # for fully filled limit orders, do nothing (not added to book)

    return trades

